INSERT INTO `mdl_adminpresets` VALUES
(1,0,'Başlatıcı','Ödev, Geri Bildirim, Forum, H5P, Test ve Tamamlama takibi dahil olmak üzere en popüler özelliklerin tümüne sahip Moodle.','http://localhost:8080','','','',1,1790678853,0),
