(52,'H5P.GoalsAssessmentPage','Goals assessment page',1,4,27,0,0,'','goals-assessment-page.js','goals-assessment-page.css','','[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the goals assessment page.\",\n    \"default\": \"Rate the goals that you have chosen in the goals page.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"lowRating\",\n    \"label\": \"Low rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for worst rating.\",\n    \"default\": \"Learned little\"\n  },\n  {\n    \"name\": \"midRating\",\n    \"label\": \"Medium rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for middle rating.\",\n    \"default\": \"Learned something\"\n  },\n  {\n    \"name\": \"highRating\",\n    \"label\": \"High rating text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text for great rating.\",\n    \"default\": \"Learned a lot\"\n  },\n  {\n    \"name\": \"noGoalsText\",\n    \"label\": \"No goals text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Feedback text when no goals have been created.\",\n    \"default\": \"You have not chosen any goals yet.\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"legendHeader\",\n    \"label\": \"Legend header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Possible ratings:\"\n  },\n  {\n    \"name\": \"goalHeader\",\n    \"label\": \"Goal header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Goals\"\n  },\n  {\n    \"name\": \"ratingHeader\",\n    \"label\": \"Rating header\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Rating\"\n  }\n]',NULL,1,28,NULL,NULL,NULL,1),
(53,'H5P.GoalsPage','Goals page',1,5,32,0,0,'','goals-page.js, goal-instance.js','goals-page.css','','[\n  {\n    \"name\": \"description\",\n    \"label\": \"Description\",\n    \"importance\": \"medium\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Description of the goals page.\",\n    \"default\": \"Insert the goals that you have chosen to work with.\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ],\n    \"optional\": true\n  },\n  {\n    \"name\": \"defineGoalText\",\n    \"label\": \"Define goal link text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed on the button for creating a new goal.\",\n    \"default\": \"Create a new goal\"\n  },\n  {\n    \"name\": \"definedGoalLabel\",\n    \"label\": \"Label for a user defined goal\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed as label on a user created goal.\",\n    \"default\": \"User defined goal\"\n  },\n  {\n    \"name\": \"defineGoalPlaceholder\",\n    \"label\": \"Define goal placeholder\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Text that will be displayed as a placeholder when creating a new goal.\",\n    \"default\": \"Write here...\"\n  },\n  {\n    \"name\": \"goalsAddedText\",\n    \"label\": \"Text indicating how many goals has been added\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Goals added:\",\n    \"description\": \"This text will follow after the amount of goals that is currently created, example: \'Goals added: 5\' where \'Goals added:\' is this text.\"\n  },\n  {\n    \"name\": \"specifyGoalText\",\n    \"label\": \"Text for \\\"Specify goal\\\"-button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Specification\"\n  },\n  {\n    \"name\": \"removeGoalText\",\n    \"label\": \"Text for \\\"Remove goal\\\"-button\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"default\": \"Remove Goal\"\n  },\n  {\n    \"name\": \"helpTextLabel\",\n    \"label\": \"Label for help text\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"description\": \"Label for showing additional helpful information to the user.\",\n    \"default\": \"More information\"\n  },\n  {\n    \"name\": \"helpText\",\n    \"label\": \"Fill in additional help information\",\n    \"importance\": \"low\",\n    \"type\": \"text\",\n    \"widget\": \"html\",\n    \"description\": \"Here you can fill in additional helpful information for the user.\",\n    \"enterMode\": \"p\",\n    \"optional\": true,\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"u\",\n      \"a\",\n      \"ul\",\n      \"ol\",\n      \"h2\",\n      \"h3\",\n      \"hr\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"goalDeletionConfirmation\",\n    \"type\": \"group\",\n    \"common\": true,\n    \"importance\": \"low\",\n    \"label\": \"Localize goal deletion confirmation\",\n    \"fields\": [\n      {\n        \"name\": \"header\",\n        \"type\": \"text\",\n        \"label\": \"Header\",\n        \"optional\": false,\n        \"default\": \"Confirm deletion\"\n      },\n      {\n        \"name\": \"message\",\n        \"type\": \"text\",\n        \"label\": \"Message\",\n        \"optional\": false,\n        \"default\": \"Are you sure you want to delete this goal?\"\n      },\n      {\n        \"name\": \"cancelLabel\",\n        \"type\": \"text\",\n        \"label\": \"Cancel button label\",\n        \"optional\": false,\n        \"default\": \"Cancel\"\n      },\n      {\n        \"name\": \"confirmLabel\",\n        \"type\": \"text\",\n        \"label\": \"Confirm button label\",\n        \"optional\": false,\n        \"default\": \"Confirm\"\n      }\n    ]\n  }\n]\n',NULL,1,28,NULL,NULL,NULL,1),
(54,'H5P.GoToQuestion','Crossroads',1,3,23,0,0,'','scripts/go-to-question.js','styles/go-to-question.css','','[\n  {\n    \"name\": \"text\",\n    \"type\": \"text\",\n    \"label\": \"Question Text\",\n    \"importance\": \"high\",\n    \"description\": \"The question that the user will make a choice based upon.\"\n  },\n  {\n    \"name\": \"choices\",\n    \"type\": \"list\",\n    \"label\": \"Choices\",\n    \"importance\": \"high\",\n    \"entity\": \"choice\",\n    \"min\": 2,\n    \"field\": {\n      \"name\": \"choice\",\n      \"type\": \"group\",\n      \"fields\": [\n        {\n          \"name\": \"text\",\n          \"type\": \"text\",\n          \"label\": \"Choice Text\",\n          \"importance\": \"high\",\n          \"description\": \"The label that will displayed on the choice button.\"\n        },\n        {\n          \"name\": \"goTo\",\n          \"type\": \"number\",\n          \"widget\": \"timecode\",\n          \"label\": \"Go To\",\n          \"importance\": \"high\",\n          \"description\": \"The target time the user will be taken to upon pressing the choice button. Enter timecode in the format M:SS.\"\n        },\n        {\n          \"name\": \"ifChosenText\",\n          \"type\": \"text\",\n          \"optional\": true,\n          \"label\": \"If Chosen Text\",\n          \"importance\": \"low\",\n          \"description\": \"An optional confirmation text that will be displayed after the user has pressed the choice button.\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"continueButtonLabel\",\n    \"type\": \"text\",\n    \"label\": \"Continue Button Label\",\n    \"importance\": \"low\",\n    \"default\": \"Continue\",\n    \"common\": true\n  }\n]',NULL,1,28,'{\"disable\":true,\"disableExtraTitleField\":true}',NULL,NULL,1),
