(67,'H5P.MultiMediaChoice','Multimedia Choice',0,3,77,1,0,'iframe','dist/h5p-multi-media-choice.js','dist/h5p-multi-media-choice.css','','[\n  {\n    \"name\": \"media\",\n    \"type\": \"group\",\n    \"label\": \"Media\",\n    \"importance\": \"medium\",\n    \"fields\": [\n      {\n        \"name\": \"type\",\n        \"type\": \"library\",\n        \"label\": \"Type\",\n        \"importance\": \"medium\",\n        \"options\": [\n          \"H5P.Image 1.1\",\n          \"H5P.Video 1.6\",\n          \"H5P.Audio 1.5\"\n        ],\n        \"optional\": true,\n        \"description\": \"Optional media to display above the question.\"\n      },\n      {\n        \"name\": \"disableImageZooming\",\n        \"type\": \"boolean\",\n        \"label\": \"Disable image zooming\",\n        \"importance\": \"low\",\n        \"default\": false,\n        \"optional\": true,\n        \"widget\": \"showWhen\",\n        \"showWhen\": {\n          \"rules\": [\n            {\n              \"field\": \"type\",\n              \"equals\": \"H5P.Image 1.1\"\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"question\",\n    \"type\": \"text\",\n    \"importance\": \"high\",\n    \"widget\": \"html\",\n    \"label\": \"Question\",\n    \"enterMode\": \"p\",\n    \"tags\": [\n      \"strong\",\n      \"em\",\n      \"sub\",\n      \"sup\",\n      \"h2\",\n      \"h3\",\n      \"pre\",\n      \"code\"\n    ]\n  },\n  {\n    \"name\": \"options\",\n    \"type\": \"list\",\n    \"importance\": \"high\",\n    \"label\": \"Available options\",\n    \"entity\": \"option\",\n    \"min\": 2,\n    \"max\": 20,\n    \"defaultNum\": 2,\n    \"field\": {\n      \"name\": \"option\",\n      \"type\": \"group\",\n      \"label\": \"Option\",\n      \"importance\": \"high\",\n      \"fields\": [\n        {\n          \"name\": \"media\",\n          \"type\": \"library\",\n          \"label\": \"Media\",\n          \"optional\": false,\n          \"description\": \"Media to display as a choice.\",\n          \"options\": [\n            \"H5P.Image 1.1\",\n            \"H5P.Video 1.6\",\n            \"H5P.Audio 1.5\"\n          ]\n        },\n        {\n          \"name\": \"poster\",\n          \"type\": \"image\",\n          \"label\": \"Poster image\",\n          \"importance\": \"low\",\n          \"widget\": \"showWhen\",\n          \"showWhen\": {\n            \"rules\": [\n              {\n                \"field\": \"media\",\n                \"equals\": \"H5P.Audio 1.5\"\n              }\n            ]\n          }\n        },\n        {\n          \"name\": \"correct\",\n          \"type\": \"boolean\",\n          \"label\": \"Correct\",\n          \"importance\": \"low\"\n        }\n      ]\n    }\n  },\n  {\n    \"name\": \"overallFeedback\",\n    \"type\": \"group\",\n    \"label\": \"Overall Feedback\",\n    \"importance\": \"low\",\n    \"expanded\": true,\n    \"fields\": [\n      {\n        \"name\": \"overallFeedback\",\n        \"type\": \"list\",\n        \"widgets\": [\n          {\n            \"name\": \"RangeList\",\n            \"label\": \"Default\"\n          }\n        ],\n        \"importance\": \"high\",\n        \"label\": \"Define custom feedback for any score range\",\n        \"description\": \"Click the \\\"Add range\\\" button to add as many ranges as you need. Example: 0-20% Bad score, 21-91% Average Score, 91-100% Great Score!\",\n        \"entity\": \"range\",\n        \"min\": 1,\n        \"defaultNum\": 1,\n        \"optional\": true,\n        \"field\": {\n          \"name\": \"overallFeedback\",\n          \"type\": \"group\",\n          \"importance\": \"low\",\n          \"fields\": [\n            {\n              \"name\": \"from\",\n              \"type\": \"number\",\n              \"label\": \"Score Range\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 0,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"to\",\n              \"type\": \"number\",\n              \"min\": 0,\n              \"max\": 100,\n              \"default\": 100,\n              \"unit\": \"%\"\n            },\n            {\n              \"name\": \"feedback\",\n              \"type\": \"text\",\n              \"label\": \"Feedback for defined score range\",\n              \"importance\": \"low\",\n              \"placeholder\": \"Fill in the feedback\",\n              \"optional\": true\n            }\n          ]\n        }\n      }\n    ]\n  },\n  {\n    \"name\": \"behaviour\",\n    \"type\": \"group\",\n    \"label\": \"Behavioural settings\",\n    \"importance\": \"low\",\n    \"description\": \"These options will let you control how the task behaves.\",\n    \"fields\": [\n      {\n        \"name\": \"enableRetry\",\n        \"label\": \"Enable \\\"Retry\\\" button\",\n        \"type\": \"boolean\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"name\": \"enableSolutionsButton\",\n        \"label\": \"Enable \\\"Show Solution\\\" button\",\n        \"type\": \"boolean\",\n        \"importance\": \"low\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"name\": \"confirmCheckDialog\",\n        \"label\": \"Show confirmation dialog on \\\"Check\\\"\",\n        \"importance\": \"low\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"optional\": true\n      },\n      {\n        \"name\": \"confirmRetryDialog\",\n        \"label\": \"Show confirmation dialog on \\\"Retry\\\"\",\n        \"importance\": \"low\",\n        \"type\": \"boolean\",\n        \"default\": false,\n        \"optional\": true\n      },\n      {\n        \"name\": \"singlePoint\",\n        \"type\": \"boolean\",\n        \"label\": \"Give one point for the whole question\",\n        \"importance\": \"low\",\n        \"description\": \"Awards one point to the question if the percentage score is higher than the pass percentage\",\n        \"default\": false\n      },\n      {\n        \"label\": \"Require answer before the solution can be viewed\",\n        \"importance\": \"low\",\n        \"name\": \"showSolutionsRequiresInput\",\n        \"type\": \"boolean\",\n        \"default\": true,\n        \"optional\": true\n      },\n      {\n        \"name\": \"questionType\",\n        \"type\": \"select\",\n        \"label\": \"Question Type\",\n        \"importance\": \"low\",\n        \"description\": \"Select the look and behaviour of the question.\",\n        \"default\": \"auto\",\n        \"options\": [\n          {\n            \"value\": \"auto\",\n            \"label\": \"Automatic\"\n          },\n          {\n            \"value\": \"multi\",\n            \"label\": \"Multiple Choice (Checkboxes)\"\n          },\n          {\n            \"value\": \"single\",\n            \"label\": \"Single Choice (Radio Buttons)\"\n          }\n        ]\n      },\n      {\n        \"name\": \"aspectRatio\",\n        \"type\": \"select\",\n        \"label\": \"Aspect ratio\",\n        \"importance\": \"low\",\n        \"description\": \"Select the aspect ratio of the alternatives\",\n        \"default\": \"auto\",\n        \"options\": [\n          {\n            \"value\": \"auto\",\n            \"label\": \"Automatic\"\n          },\n          {\n            \"value\": \"16to9\",\n            \"label\": \"16:9\"\n          },\n          {\n            \"value\": \"4to3\",\n            \"label\": \"4:3\"\n          },\n          {\n            \"value\": \"3to2\",\n            \"label\": \"3:2\"\n          },\n          {\n            \"value\": \"1to1\",\n            \"label\": \"1:1\"\n          }\n        ]\n      },\n      {\n        \"name\": \"maxAlternativesPerRow\",\n        \"type\": \"select\",\n        \"label\": \"Maximum alternatives per row\",\n        \"description\": \"Set the maximum number of alternatives per row to ensure the questions loo