(16,6,3,'deferredfeedback',23,1,1.0000000,0.0000000,1.0000000,0,'sa\n','as','as',1791221223),
(17,7,1,'adaptive_adapted_for_coderunner',141,1,10.0000000,0.0000000,1.0000000,0,'Klavyeden bir tam sayı N okuyun. N\'in 1\'den 5\'e kadar çarpımını her satırda n x k = sonuç biçiminde yazdırın.\n\nÖrnek: 3 → 3 x 1 = 3 ... 3 x 5 = 15\n','n = int(input())\r\nfor k in range(1, 6):\r\n    print(f\'{n} x {k} = {n * k}\')',NULL,1791454646),
(18,7,2,'adaptive_adapted_for_coderunner',142,1,15.0000000,0.0000000,1.0000000,0,'en_uzun_kelime(cumle) fonksiyonunu yazın. Boşluklarla ayrılmış cümledeki EN UZUN kelimeyi döndürsün. Eşit uzunlukta birden çok kelime varsa ILK geçeni döndürsün. Cümle boşsa \'\' döndürsün.\n','def en_uzun_kelime(cumle):\r\n    en = \'\'\r\n    for k in cumle.split():\r\n        if len(k) > len(en):\r\n            en = k\r\n    return en',NULL,1791454653),
(19,7,3,'adaptive_adapted_for_coderunner',145,1,15.0000000,0.0000000,1.0000000,0,'mukemmel_mi[Hayır] fonksiyonu, N pozitif bir tam sayı ve kendisi hariç bölenlerinin toplamı N\'e eşitse True, değilse False döndürsün. N < 2 için False. (Örnek: 6 = 1+2+3)\n','def mukemmel_mi(n):\n    if n < 2:\n        return False\n    return sum(i for i in range(1, n) if n % i == 0) == n\n',NULL,1791454596),
(20,7,4,'adaptive_adapted_for_coderunner',146,1,20.0000000,0.0000000,1.0000000,0,'Dikdortgen sınıfını yazın. Kurucu (en, boy) alsın. alan() ve cevre() metotları olsun. kare_mi() en = boy ise True olsun. En veya boy 0 ya da negatifse kurucu ValueError(\'gecersiz\') fırlatsın.\n','class Dikdortgen:\n    def __init__(self, en, boy):\n        if en <= 0 or boy <= 0:\n            raise ValueError(\'gecersiz\')\n        self.en = en\n        self.boy = boy\n\n    def alan(self):\n        return self.en * self.boy\n\n    def cevre(self):\n        return 2 * (self.en + self.boy)\n\n    def kare_mi(self):\n        return self.en == self.boy\n',NULL,1791454596),
(21,8,1,'adaptive_adapted_for_coderunner',141,1,10.0000000,0.0000000,1.0000000,0,'Klavyeden bir tam sayı N okuyun. N\'in 1\'den 5\'e kadar çarpımını her satırda n x k = sonuç biçiminde yazdırın.\n\nÖrnek: 3 → 3 x 1 = 3 ... 3 x 5 = 15\n','n = int(input())\r\nfor k in range(1, 6):\r\n    print(f\'{n} x {k} = {n * k}\')','number = int(input())\r\nfor i in range(1,6):\r\n   print(f\"{number} x {i} =\",number*i)',1791457401),
(22,8,2,'adaptive_adapted_for_coderunner',142,1,15.0000000,0.0000000,1.0000000,0,'en_uzun_kelime(cumle) fonksiyonunu yazın. Boşluklarla ayrılmış cümledeki EN UZUN kelimeyi döndürsün. Eşit uzunlukta birden çok kelime varsa ILK geçeni döndürsün. Cümle boşsa \'\' döndürsün.\n','def en_uzun_kelime(cumle):\r\n    en = \'\'\r\n    for k in cumle.split():\r\n        if len(k) > len(en):\r\n            en = k\r\n    return en','print(\"Ali\")',1791457401),
(23,8,3,'adaptive_adapted_for_coderunner',145,1,15.0000000,0.0000000,1.0000000,0,'mukemmel_mi[Hayır] fonksiyonu, N pozitif bir tam sayı ve kendisi hariç bölenlerinin toplamı N\'e eşitse True, değilse False döndürsün. N < 2 için False. (Örnek: 6 = 1+2+3)\n','def mukemmel_mi(n):\n    if n < 2:\n        return False\n    return sum(i for i in range(1, n) if n % i == 0) == n\n','print(\"ali\")',1791457401),
(24,8,4,'adaptive_adapted_for_coderunner',146,1,20.0000000,0.0000000,1.0000000,0,'Dikdortgen sınıfını yazın. Kurucu (en, boy) alsın. alan() ve cevre() metotları olsun. kare_mi() en = boy ise True olsun. En veya boy 0 ya da negatifse kurucu ValueError(\'gecersiz\') fırlatsın.\n','class Dikdortgen:\n    def __init__(self, en, boy):\n        if en <= 0 or boy <= 0:\n            raise ValueError(\'gecersiz\')\n        self.en = en\n        self.boy = boy\n\n    def alan(self):\n        return self.en * self.boy\n\n    def cevre(self):\n        return 2 * (self.en + self.boy)\n\n    def kare_mi(self):\n        return self.en == self.boy\n','print(\"Ali\")',1791457401),
(26,10,1,'adaptive_adapted_for_coderunner',141,1,10.0000000,0.0000000,1.0000000,0,'Klavyeden bir tam sayı N okuyun. N\'in 1\'den 5\'e kadar çarpımını her satırda n x k = sonuç biçiminde yazdırın.\n\nÖrnek: 3 → 3 x 1 = 3 ... 3 x 5 = 15\n','n = int(input())\r\nfor k in range(1, 6):\r\n    print(f\'{n} x {k} = {n * k}\')','n = int(input())\r\nfor i in range(1, 6):\r\n    print(n , \"x\", i , \"=\", n * i)',1791458452),
