INSERT INTO `mdl_scale` VALUES
(1,0,0,'Ayrı ve Bağlantılı bilgi yolları','Çoğunlukla ayrık bilgi,Ayrık ve bağlantılı,Çoğunlukla bağlantılı bilgi','Ölçekleme ayrık ve bağlantılı bilgi teorisi üzerine kuruludur. Bu teori, birşeyi hesaplamak ya da öğrenmek için kullandığımız görme ve duyma yetilerini açıklar.<ul><li><strong>Ayrık bilenler</strong> objektif olarak duygu ve hisleri hesaba katmayacaklardır. Diğer insanlarla tartışmalarda, kendi fikirlerini savunurken, karşı tarafın açıklarını bulmak için mantıklarını kullanmayı severler.</li><li><strong>Bağlantılı bilenler</strong> diğer insanlara karşı daha esnektir. \"Karşı bakış açısından birşeyler anlayabildikleri\" sürece karşı tarafla empati kurma, dinleme ve sorular sorma yetilerine sahiptirler. Bu insanlar deneyimlerini paylaşarak diğer insanlardaki bilgiyi keşfetme yöntemini kullanırlar.</li></ul>',0,1790678853),
(2,0,0,'Varsayılan yetki ölçeği','Henüz yetkin değil,Yetkin','Birisinin yetkinlik gösterip göstermediği hakkında daha fazla bilgi sağlayan ikili derecelendirme ölçeği.',0,1790678853);
